mapper.select:
/* BmsTotalManageMapper.selectTotalManageList : 통합관리 Master 조회 (2025.12.18 수정)*/ WITH M_DEST AS ( -- 0. 도착일시 최초 도착일시 보이도록 SELECT MBL_NO, AR_DATE, AR_TIME, FORMAT(CAST(CONCAT(DEST_DATE, ' ', DEST_TIME) AS DATETIME), 'yyyy-MM-dd HH:mm') AS DEST_DATE_TIME, ROW_NUMBER() OVER (PARTITION BY MBL_NO ORDER BY ISNULL(NULLIF(DEST_DATE,''),'9999-12-31'), SEQ ASC) AS RN FROM TB_BMS_MASTER_DEST WITH (NOLOCK) WHERE 1=1
AND AR_DATE >= #{srchStartDate} AND AR_DATE < DATEADD(DAY, 1, #{srchEndDate})
), MASTER_DEST AS ( -- 1. 마스터 정보 및 최신 날짜 정보 요약 SELECT MBL_NO, MAX(CASE WHEN RN = 1 THEN AR_DATE END) AS AR_DATE, MAX(CASE WHEN RN = 1 THEN AR_TIME END) AS AR_TIME, MAX(CASE WHEN RN = 1 THEN DEST_DATE_TIME END) AS DEST_DATE_TIME FROM M_DEST GROUP BY MBL_NO ), OUT_SUMMARY AS ( -- 2. 출고 정보 요약 (IN_NO당 1건) SELECT OP.IN_NO, MAX(O.OUT_CLASS) AS OUT_CLASS, MAX(O.OUT_SCAN_DATE_TIME) AS OUT_SCAN_DATE_TIME, MAX(O.TIC_OUT_SCAN_YN) AS TIC_OUT_SCAN_YN, MAX(OP.APPROVAL_DATE) AS APPROVAL_DATE, MAX(OP.APPROVAL_CANCEL_DATE) AS APPROVAL_CANCEL_DATE, SUM( CASE WHEN O.OUT_SCAN_DATE_TIME = '1900-01-01 00:00:00.000' THEN O.OUT_CT ELSE 0 END ) AS S_OUT_CT FROM TB_BMS_OUT_PLAN OP WITH(NOLOCK) JOIN TB_BMS_OUT O WITH(NOLOCK) ON O.OUT_PLAN_NO = OP.OUT_PLAN_NO GROUP BY OP.IN_NO ), SAMPLE_SUMMARY AS ( -- 3. 샘플 정보 요약 SELECT IN_NO, MAX(BL_NO) AS SAMPLE_BL_NO FROM TB_BMS_SAMPLE WITH(NOLOCK) GROUP BY IN_NO ), HF_SUMMARY AS ( -- 4. 5HF 정보 요약 SELECT BL_NO, MAX(DIVIDE_CLASS) AS DIVIDE_CLASS FROM TB_BMS_5HF WITH(NOLOCK) WHERE DIVIDE_CLASS IN ('1', '3') GROUP BY BL_NO ), STOCK_AGG AS ( -- 5. MBL 단위 실시간 재고 합산 SELECT TBI.MBL_NO, SUM(TBI.STOCK_CT + ISNULL(OS.S_OUT_CT, 0)) AS MBL_STOCK_CT FROM TB_BMS_IN TBI WITH(NOLOCK) LEFT JOIN OUT_SUMMARY OS ON TBI.IN_NO = OS.IN_NO GROUP BY TBI.MBL_NO HAVING SUM(TBI.STOCK_CT + ISNULL(OS.S_OUT_CT, 0)) > 0 ), MAIN_INFO AS ( -- 6. 개별 행 데이터 결합 (여기서 뻥튀기 방지됨) SELECT P.IN_PLAN_NO, P.MBL_NO, P.BL_NO, P.CARGO_REFERENCE_NO, M.AR_DATE, M.AR_TIME, P.CD_TYPE, P.IN_YN, P.VESSEL_FLIGHT, P.EX_CT, P.EX_WT, P.BIG_SIZE_YN, P.SE_INSPECTION_CODE, P.INSPECTION_TYPE, P.INSPECTION_CUSTOMS_YN, P.INTELLECTUAL_PROP_YN, I.IN_CLASS, I.XRAY_SCAN_CT, I.XRAY_INSPECTION_CODE, I.CARRYIN_DATE, I.CARRYOUT_DATE, OP.OUT_CLASS, OP.OUT_SCAN_DATE_TIME, OP.TIC_OUT_SCAN_YN, M.DEST_DATE_TIME, SS.SAMPLE_BL_NO, HF.DIVIDE_CLASS, ISNULL(S.MBL_STOCK_CT, 0) AS MBL_STOCK_CT FROM TB_BMS_IN_PLAN P WITH(NOLOCK) INNER JOIN MASTER_DEST M ON M.MBL_NO = P.MBL_NO LEFT JOIN TB_BMS_IN I WITH(NOLOCK) ON I.IN_PLAN_NO = P.IN_PLAN_NO LEFT JOIN OUT_SUMMARY OP ON OP.IN_NO = I.IN_NO LEFT JOIN SAMPLE_SUMMARY SS ON SS.IN_NO = I.IN_NO LEFT JOIN HF_SUMMARY HF ON HF.BL_NO = P.BL_NO LEFT JOIN STOCK_AGG S ON S.MBL_NO = P.MBL_NO
WHERE 1=1
), TOTAL_INFO AS ( SELECT MI.MBL_NO, MAX(MI.AR_DATE) AS AR_DATE, MAX(MI.AR_TIME) AS AR_TIME, MAX(MI.VESSEL_FLIGHT) AS VESSEL_FLIGHT, MAX(MI.DEST_DATE_TIME) AS DEST_DATE_TIME, SUM(ISNULL(MI.EX_CT, 0)) AS CT, SUM(ISNULL(MI.EX_WT, 0)) AS WT, COUNT(MI.BL_NO) AS HBL_CNT, COUNT(CASE MI.CD_TYPE WHEN 'Y' THEN 1 END) AS SIMPLE_CNT, COUNT(CASE MI.CD_TYPE WHEN 'N' THEN 1 END) AS GENERAL_CNT, COUNT(CASE MI.CD_TYPE WHEN 'B' THEN 1 END) AS EXCLUDE_CNT, COUNT(MI.BL_NO) AS IN_PLAN_CNT, COUNT(CASE WHEN MI.IN_CLASS <> '21' THEN 1 END) AS CARRY_IN_CNT, COUNT(CASE WHEN MI.IN_YN = 'N' THEN 1 END) AS NO_CARRYIN_CNT, COUNT(CASE WHEN MI.XRAY_SCAN_CT <> 0 THEN 1 END) AS XRAY_CNT, COUNT(CASE WHEN MI.OUT_CLASS <> '61' AND ISNULL(MI.CARRYOUT_DATE, '') <> '' THEN 1 END) AS CARRY_OUT_CNT, MAX(MI.MBL_STOCK_CT) AS STOCK_CNT, --MAX로 변경 COUNT(CASE WHEN MI.TIC_OUT_SCAN_YN = 'Y' THEN 1 END) AS MOVE_CARRY_OUT_CNT, COUNT(CASE WHEN MI.IN_CLASS = '21' THEN 1 END) AS MOVE_CARRY_IN_CNT, COUNT(MI.SAMPLE_BL_NO) AS SAMPLE_OUT_CNT, COUNT(CASE WHEN MI.DIVIDE_CLASS = '3' THEN 1 END) AS PARTIAL_CNT, COUNT(CASE WHEN MI.DIVIDE_CLASS = '1' THEN 1 END) AS MAINTENANCE_CNT, COUNT(CASE MI.BIG_SIZE_YN WHEN 'Y' THEN 1 END) AS BIG_SIZE_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '01' THEN 1 END) AS SE_INSP01_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '02' THEN 1 END) AS SE_INSP02_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '03' THEN 1 END) AS SE_INSP03_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '05' THEN 1 END) AS SE_INSP05_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '06' THEN 1 END) AS SE_INSP06_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = 'C' THEN 1 END) AS SE_INSP07_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '5' THEN 1 END) AS INSP05_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '6' THEN 1 END) AS INSP06_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '8' THEN 1 END) AS INSP08_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '9' THEN 1 END) AS INSP09_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '10' THEN 1 END) AS INSP10_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '11' THEN 1 END) AS INSP11_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '01' THEN 1 END) AS XRAY01_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '02' THEN 1 END) AS XRAY02_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '03' THEN 1 END) AS XRAY03_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '04' THEN 1 END) AS XRAY04_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '06' THEN 1 END) AS XRAY06_CNT, COUNT(CASE WHEN MI.INSPECTION_CUSTOMS_YN = 'Y' THEN 1 END) AS INSP_CUSTOMS_CNT, COUNT(CASE WHEN MI.INTELLECTUAL_PROP_YN = 'Y' THEN 1 END) AS INTELL_PROP_CNT, CASE WHEN COUNT(CASE WHEN MI.IN_CLASS <> '21' THEN 1 END) = 0 THEN '반입예정' WHEN COUNT(MI.BL_NO) > COUNT(CASE WHEN MI.IN_CLASS <> '21' THEN 1 END) THEN '반입중' WHEN COUNT(MI.BL_NO) <= COUNT(CASE WHEN MI.IN_CLASS <> '21' THEN 1 END) THEN '반입완료' WHEN COUNT(MI.BL_NO) > COUNT(CASE WHEN MI.OUT_CLASS <> '61' AND ISNULL(MI.CARRYOUT_DATE, '') <> '' THEN 1 END) THEN '반출중' WHEN COUNT(MI.BL_NO) <= COUNT(CASE WHEN MI.OUT_CLASS <> '61' AND ISNULL(MI.CARRYOUT_DATE, '') <> '' THEN 1 END) THEN '반출완료' END AS LAST_POD_STATUS FROM MAIN_INFO MI GROUP BY MI.MBL_NO ) SELECT *, ROW_NUMBER() OVER(ORDER BY MBL_NO) AS NUM, COUNT(*) OVER() AS TOTAL FROM TOTAL_INFO
OFFSET ${startNum} ROWS FETCH NEXT ${pageSize} ROWS ONLY

/* BmsTotalManageMapper.selectTotalManageList_bak : 통합관리 Master 조회 (사용안함)*/ WITH MAIN_INFO AS ( SELECT P.IN_PLAN_NO, P.MBL_NO, P.BL_NO, P.CARGO_REFERENCE_NO, M.AR_DATE, M.AR_TIME, P.CD_TYPE, P.IN_YN, P.VESSEL_FLIGHT, P.EX_CT, P.EX_WT, P.BIG_SIZE_YN, P.SE_INSPECTION_CODE, P.INSPECTION_TYPE, P.INSPECTION_CUSTOMS_YN, P.INTELLECTUAL_PROP_YN, I.IN_CLASS, I.XRAY_SCAN_CT, I.XRAY_INSPECTION_CODE, I.CARRYIN_DATE, I.CARRYOUT_DATE, O.OUT_CLASS, O.OUT_SCAN_DATE_TIME, O.TIC_OUT_SCAN_YN, ( SELECT TOP 1 FORMAT(CAST(CONCAT(MD.DEST_DATE, ' ', MD.DEST_TIME) AS DATETIME), 'yyyy-MM-dd HH:mm') FROM TB_BMS_MASTER_DEST MD WITH(NOLOCK) WHERE MD.MBL_NO = P.MBL_NO ORDER BY MD.DEST_DATE DESC, MD.DEST_TIME DESC ) AS DEST_DATE_TIME, BS.BL_NO AS SAMPLE_BL_NO, HF.DIVIDE_CLASS, ( SELECT TOP 1 ISNULL(TBI.STOCK_CT + TBO.S_OUT_CT, 0) FROM TB_BMS_IN TBI WITH (NOLOCK) LEFT JOIN ( SELECT IN_NO , MAX(MBL_NO) AS MBL_NO , SUM(OUT_CT) AS S_OUT_CT FROM TB_BMS_OUT WITH (NOLOCK) WHERE 1=1 AND OUT_SCAN_DATE_TIME = '1900-01-01 00:00:00.000' GROUP BY IN_NO ) TBO ON TBI.IN_NO = TBO.IN_NO WHERE TBI.MBL_NO = P.MBL_NO AND TBI.AR_DATE = P.AR_DATE AND TBI.AR_TIME = P.AR_TIME AND TBI.VESSEL_FLIGHT = P.VESSEL_FLIGHT AND TBI.STOCK_CT + ISNULL(TBO.S_OUT_CT, 0) > 0 ) AS MBL_STOCK_CT FROM TB_BMS_IN_PLAN P WITH(NOLOCK) LEFT JOIN TB_BMS_IN I WITH(NOLOCK) ON I.IN_PLAN_NO = P.IN_PLAN_NO LEFT JOIN TB_BMS_OUT_PLAN OP WITH(NOLOCK) ON OP.IN_NO = I.IN_NO LEFT JOIN TB_BMS_OUT O WITH(NOLOCK) ON O.OUT_PLAN_NO = OP.OUT_PLAN_NO LEFT JOIN TB_BMS_SAMPLE BS WITH(NOLOCK) ON BS.IN_NO = I.IN_NO LEFT JOIN TB_BMS_5HF HF WITH(NOLOCK) ON HF.BL_NO = P.BL_NO AND HF.DIVIDE_CLASS IN ('1', '3')
LEFT JOIN ( SELECT MBL_NO, LEFT(MAX(AR_DATE + AR_TIME), 10) AS AR_DATE, RIGHT(MAX(AR_DATE + AR_TIME), 5) AS AR_TIME FROM TB_BMS_MASTER_DEST WITH(NOLOCK) GROUP BY MBL_NO ) M ON M.MBL_NO = P.MBL_NO WHERE 1=1
), TOTAL_INFO AS ( SELECT MI.MBL_NO, MAX(MI.AR_DATE) AS AR_DATE, MAX(MI.AR_TIME) AS AR_TIME, MAX(MI.VESSEL_FLIGHT) AS VESSEL_FLIGHT, MAX(MI.DEST_DATE_TIME) AS DEST_DATE_TIME, SUM(ISNULL(MI.EX_CT, 0)) AS CT, SUM(ISNULL(MI.EX_WT, 0)) AS WT, COUNT(MI.BL_NO) AS HBL_CNT, COUNT(CASE MI.CD_TYPE WHEN 'Y' THEN 1 END) AS SIMPLE_CNT, COUNT(CASE MI.CD_TYPE WHEN 'N' THEN 1 END) AS GENERAL_CNT, COUNT(CASE MI.CD_TYPE WHEN 'B' THEN 1 END) AS EXCLUDE_CNT, COUNT(MI.BL_NO) AS IN_PLAN_CNT, COUNT(CASE WHEN MI.IN_CLASS <> '21' THEN 1 END) AS CARRY_IN_CNT, COUNT(CASE WHEN MI.IN_YN = 'N' THEN 1 END) AS NO_CARRYIN_CNT, COUNT(CASE WHEN MI.XRAY_SCAN_CT <> 0 THEN 1 END) AS XRAY_CNT, COUNT(CASE WHEN MI.OUT_CLASS <> '61' AND ISNULL(MI.CARRYOUT_DATE, '') <> '' THEN 1 END) AS CARRY_OUT_CNT, SUM(MI.MBL_STOCK_CT) AS STOCK_CNT, COUNT(CASE WHEN MI.TIC_OUT_SCAN_YN = 'Y' THEN 1 END) AS MOVE_CARRY_OUT_CNT, COUNT(CASE WHEN MI.IN_CLASS = '21' THEN 1 END) AS MOVE_CARRY_IN_CNT, COUNT(MI.SAMPLE_BL_NO) AS SAMPLE_OUT_CNT, COUNT(CASE WHEN MI.DIVIDE_CLASS = '3' THEN 1 END) AS PARTIAL_CNT, COUNT(CASE WHEN MI.DIVIDE_CLASS = '1' THEN 1 END) AS MAINTENANCE_CNT, COUNT(CASE MI.BIG_SIZE_YN WHEN 'Y' THEN 1 END) AS BIG_SIZE_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '01' THEN 1 END) AS SE_INSP01_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '02' THEN 1 END) AS SE_INSP02_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '03' THEN 1 END) AS SE_INSP03_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '05' THEN 1 END) AS SE_INSP05_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = '06' THEN 1 END) AS SE_INSP06_CNT, COUNT(CASE WHEN MI.SE_INSPECTION_CODE = 'C' THEN 1 END) AS SE_INSP07_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '5' THEN 1 END) AS INSP05_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '6' THEN 1 END) AS INSP06_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '8' THEN 1 END) AS INSP08_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '9' THEN 1 END) AS INSP09_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '10' THEN 1 END) AS INSP10_CNT, COUNT(CASE WHEN MI.INSPECTION_TYPE = '11' THEN 1 END) AS INSP11_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '01' THEN 1 END) AS XRAY01_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '02' THEN 1 END) AS XRAY02_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '03' THEN 1 END) AS XRAY03_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '04' THEN 1 END) AS XRAY04_CNT, COUNT(CASE WHEN MI.XRAY_INSPECTION_CODE = '06' THEN 1 END) AS XRAY06_CNT, COUNT(CASE WHEN MI.INSPECTION_CUSTOMS_YN = 'Y' THEN 1 END) AS INSP_CUSTOMS_CNT, COUNT(CASE WHEN MI.INTELLECTUAL_PROP_YN = 'Y' THEN 1 END) AS INTELL_PROP_CNT, CASE WHEN COUNT(CASE WHEN MI.IN_CLASS <> '21' THEN 1 END) = 0 THEN '반입예정' WHEN COUNT(MI.BL_NO) > COUNT(CASE WHEN MI.IN_CLASS <> '21' THEN 1 END) THEN '반입중' WHEN COUNT(MI.BL_NO) <= COUNT(CASE WHEN MI.IN_CLASS <> '21' THEN 1 END) THEN '반입완료' WHEN COUNT(MI.BL_NO) > COUNT(CASE WHEN MI.OUT_CLASS <> '61' AND ISNULL(MI.CARRYOUT_DATE, '') <> '' THEN 1 END) THEN '반출중' WHEN COUNT(MI.BL_NO) <= COUNT(CASE WHEN MI.OUT_CLASS <> '61' AND ISNULL(MI.CARRYOUT_DATE, '') <> '' THEN 1 END) THEN '반출완료' END AS LAST_POD_STATUS FROM MAIN_INFO MI
GROUP BY MI.MBL_NO ) SELECT *, ROW_NUMBER() OVER(ORDER BY MBL_NO, AR_DATE, AR_TIME) AS NUM, COUNT(*) OVER() AS TOTAL FROM TOTAL_INFO
OFFSET ${startNum} ROWS FETCH NEXT ${pageSize} ROWS ONLY

/* BmsTotalManageMapper.selectEmDeliveryCount : 택배 차수 조회 */
SELECT
	CAST(EMP_ID AS INT)
FROM
	TB_BMS_OUT_DELIVERY WITH (NOLOCK)
WHERE
	DELIVERY_CODE = #{srchDeliveryTypeGbn}
	AND APPROVAL_CLASS = '31'
	AND FORMAT(CAST(REGISTER_DATE_TIME AS DATETIME), 'yyyy-MM-dd') = #{srchDeliveryDate}
GROUP BY EMP_ID

/* BmsTotalManageMapper.selectEmDeliveryListExcel : 우체국 택배 Excel 조회 */ WITH LastStatus AS ( SELECT PACKING_NO, APPROVAL_CLASS, ROW_NUMBER() OVER (PARTITION BY PACKING_NO ORDER BY REGISTER_DATE_TIME DESC) AS RN FROM TB_BMS_OUT_DELIVERY WITH (NOLOCK) WHERE DELIVERY_CODE = 'EM' AND FORMAT(CAST(REGISTER_DATE_TIME AS DATETIME), 'yyyy-MM-dd') = #{srchDeliveryDate}
AND EMP_ID = #{empId}
), Valid AS ( SELECT PACKING_NO FROM LastStatus WHERE RN = 1 AND APPROVAL_CLASS = '31' ), Latest AS ( SELECT D.*, ROW_NUMBER() OVER ( PARTITION BY D.PACKING_NO ORDER BY D.REGISTER_DATE_TIME DESC ) AS RN2 FROM TB_BMS_OUT_DELIVERY D WITH (NOLOCK) INNER JOIN Valid V ON D.PACKING_NO = V.PACKING_NO ), Filtered AS ( SELECT L.PACKING_NO, L.REGISTER_DATE_TIME, CASE WHEN TBIPP.WEIGHING_WT > 0 THEN TBIPP.WEIGHING_WT WHEN L.EMP_ID > 0 THEN L.EMP_ID ELSE CAST(ROUND(ISNULL(TBIP.EX_WT, 0) * 1000 / ISNULL(TBIP.EX_CT, 1), 0) AS INT) END AS EX_WT, --TBIP.EX_WT, TBIPP.DIM_WIDTH, TBIPP.DIM_LENGTH, TBIPP.DIM_HEIGHT FROM Latest L
LEFT JOIN TB_BMS_IN_PLAN_PKG TBIPP WITH (NOLOCK) ON L.PACKING_NO = TBIPP.PACKING_NO LEFT JOIN TB_BMS_IN_PLAN TBIP WITH (NOLOCK) ON TBIP.IN_PLAN_NO = TBIPP.IN_PLAN_NO WHERE L.RN2 = 1 ) SELECT ROW_NUMBER() OVER (ORDER BY REGISTER_DATE_TIME) AS num, PACKING_NO AS packingNo, '0' AS idenNum, '식별번호 없음' AS countryName, 'CH7' AS ipsNum, CONVERT(VARCHAR(21), REGISTER_DATE_TIME, 120) AS scanDate,
EX_WT AS gWt, CAST(ROUND((DIM_WIDTH + DIM_LENGTH + DIM_HEIGHT) / 10.0, 0) AS INT) AS vWt FROM Filtered ORDER BY REGISTER_DATE_TIME
